import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { ImagePlus, Search } from "lucide-react";

export default function PostAttributesPage() {
  const { category } = useParams();

  // Form State
  const [formData, setFormData] = useState({
    title: "",
    description: "",
    price: "",
    category: category || "Vehicles",
    location: "",
    images: [],
    brand: "",
    name: "Lawal Muazu",
    phoneNumber: "",
    paymentOptions: [],
    contactMethod: [],
  });

  const paymentOptions = ["Cash", "Exchange", "Installments", "Cash or Installment"];
  const contactMethods = ["Phone Number", "Dubizzle Chat", "Both"];

  // Update category when URL parameter changes
  useEffect(() => {
    setFormData((prevData) => ({ ...prevData, category: category || "Vehicles" }));
  }, [category]);

  // Handle input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  // Handle checkbox changes
  const handleCheckboxChange = (e, type) => {
    const { value, checked } = e.target;
    setFormData((prevData) => {
      const selected = new Set(prevData[type]);
      if (checked) selected.add(value);
      else selected.delete(value);
      return { ...prevData, [type]: Array.from(selected) };
    });
  };

  // Handle image upload
  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files);
    setFormData((prevData) => ({ ...prevData, images: files }));
  };

  // Form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    alert("Form submitted successfully!");
    console.log(formData); // For debugging
  };

  return (
    <div className="container mx-auto px-4 py-6">
      {/* Header Section */}
      <div className="mb-6 text-center">
        <h1 className="text-2xl font-semibold text-gray-800">POST YOUR AD</h1>
      </div>

      {/* Form Section */}
      <form
        onSubmit={handleSubmit}
        className="bg-white shadow-md rounded-md p-6 space-y-6 max-w-3xl mx-auto"
      >
        {/* Category */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Category</label>
          <div className="flex items-center justify-between border border-gray-300 rounded-md p-4 bg-gray-50">
            <div className="flex items-center space-x-2">
              <span className="p-2 bg-red-100 rounded-md text-red-500">
                <ImagePlus className="w-6 h-6" />
              </span>
              <div>
                <p className="font-medium text-gray-800">{formData.category}</p>
                <p className="text-sm text-gray-500">Cars for Sale</p>
              </div>
            </div>
            <button
              type="button"
              className="text-red-500 font-medium hover:underline"
              onClick={() => alert("Change category clicked")}
            >
              Change
            </button>
          </div>
        </div>

        {/* Upload Images */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Upload Images</label>
          <div className="grid grid-cols-4 gap-2">
            {Array.from({ length: 12 }).map((_, index) => (
              <div
                key={index}
                className="border border-gray-300 rounded-md flex items-center justify-center h-20 cursor-pointer"
              >
                <ImagePlus className="w-6 h-6 text-gray-400" />
              </div>
            ))}
          </div>
          <p className="mt-2 text-sm text-gray-500">
            For the cover picture we recommend using the landscape mode.
          </p>
        </div>

        {/* Location */}
        <div>
          <label htmlFor="location" className="block text-gray-700 font-medium mb-1">
            Location*
          </label>
          <input
            type="text"
            id="location"
            name="location"
            value={formData.location}
            onChange={handleInputChange}
            className="block w-full border border-gray-300 rounded-md p-2"
            placeholder="Select Location"
          />
        </div>

        {/* Payment Options */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Payment Options</label>
          <div className="grid grid-cols-2 gap-2">
            {paymentOptions.map((option) => (
              <label key={option} className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  value={option}
                  onChange={(e) => handleCheckboxChange(e, "paymentOptions")}
                  checked={formData.paymentOptions.includes(option)}
                />
                <span>{option}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Price */}
        <div>
          <label htmlFor="price" className="block text-gray-700 font-medium mb-1">
            Price*
          </label>
          <div className="flex items-center">
            <span className="px-4 py-2 bg-gray-100 border border-gray-300 rounded-l-md">EGP</span>
            <input
              type="number"
              id="price"
              name="price"
              value={formData.price}
              onChange={handleInputChange}
              className="block w-full border-t border-b border-r border-gray-300 rounded-r-md p-2"
              placeholder="Enter Price"
            />
          </div>
        </div>

        {/* Name */}
        <div>
          <label htmlFor="name" className="block text-gray-700 font-medium mb-1">
            Name*
          </label>
          <input
            type="text"
            id="name"
            name="name"
            value={formData.name}
            readOnly
            className="block w-full border border-gray-300 rounded-md p-2 bg-gray-100"
          />
        </div>

        {/* Mobile Phone Number */}
        <div>
          <label htmlFor="phoneNumber" className="block text-gray-700 font-medium mb-1">
            Mobile Phone Number*
          </label>
          <div className="flex items-center">
            <span className="px-4 py-2 bg-gray-100 border border-gray-300 rounded-l-md">+20</span>
            <input
              type="tel"
              id="phoneNumber"
              name="phoneNumber"
              value={formData.phoneNumber}
              onChange={handleInputChange}
              className="block w-full border-t border-b border-r border-gray-300 rounded-r-md p-2"
              placeholder="Enter phone number"
            />
          </div>
        </div>

        {/* Contact Method */}
        <div>
          <label className="block text-gray-700 font-medium mb-1">Contact Method</label>
          <div className="grid grid-cols-3 gap-2">
            {contactMethods.map((method) => (
              <label key={method} className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  value={method}
                  onChange={(e) => handleCheckboxChange(e, "contactMethod")}
                  checked={formData.contactMethod.includes(method)}
                />
                <span>{method}</span>
              </label>
            ))}
          </div>
        </div>

        {/* Submit Button */}
        <div>
          <button
            type="submit"
            className="w-full bg-red-500 text-white py-2 px-4 rounded-md shadow-sm hover:bg-red-600"
          >
            Post Now
          </button>
        </div>
      </form>
    </div>
  );
}
